import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageSubjects() {
  const [subjects, setSubjects] = useState([]);
  const [subjectCode, setSubjectCode] = useState(''); 
  const [subjectName, setSubjectName] = useState('');

  const fetchSubjects = () => axios.get('http://localhost:8081/api/view-subjects').then(res => setSubjects(res.data));
  useEffect(() => { fetchSubjects(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-subject', { subject_code: subjectCode, subject_name: subjectName })
      .then((res) => {
        if (res.data.status === "Error") alert("Error: " + res.data.error);
        else { fetchSubjects(); setSubjectCode(''); setSubjectName(''); }
      }).catch(() => alert("Error adding subject!"));
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this subject?")) {
      axios.delete(`http://localhost:8081/api/delete-subject/${id}`).then(() => fetchSubjects());
    }
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh', animation: 'fadeIn 0.5s' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#fff', padding: '20px 30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '25px' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px', display: 'flex', alignItems: 'center', gap: '10px' }}>📚 Manage Subjects</h2>
      </div>

      <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '30px' }}>
        <h3 style={{ margin: '0 0 15px 0', color: '#475569', fontSize: '16px' }}>Add New Subject</h3>
        <form onSubmit={handleSubmit} style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          <input type="text" placeholder="Subject Code (e.g. SUB05)" value={subjectCode} onChange={(e) => setSubjectCode(e.target.value)} required style={styles.input} />
          <input type="text" placeholder="Enter new subject name..." value={subjectName} onChange={(e) => setSubjectName(e.target.value)} required style={{...styles.input, flex: 1}} />
          <button type="submit" style={styles.primaryBtn}>+ Add Subject</button>
        </form>
      </div>

      <div style={styles.tableContainer}>
        <table style={styles.table}>
          <thead>
            <tr style={{ backgroundColor: '#f1f5f9' }}>
              <th style={styles.th}>Subject ID</th><th style={styles.th}>Subject Code</th><th style={styles.th}>Subject Name</th><th style={{...styles.th, textAlign: 'center'}}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {subjects.map(s => (
              <tr key={s.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{...styles.td, color: '#64748b'}}>#{s.id}</td>
                <td style={{...styles.td, fontWeight: 'bold', color: '#0369a1'}}>{s.subject_code}</td>
                <td style={{...styles.td, fontSize: '15px', fontWeight: 'bold', color: '#15803d'}}>{s.subject_name}</td>
                <td style={{...styles.td, textAlign: 'center'}}>
                  <button onClick={() => handleDelete(s.id)} style={styles.deleteBtn}>🗑️ Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

    </div>
  );
}

const styles = {
  input: { padding: '12px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '14px', width: '250px' },
  primaryBtn: { padding: '12px 25px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px', whiteSpace: 'nowrap' },
  tableContainer: { backgroundColor: '#fff', borderRadius: '15px', overflowX: 'auto', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' },
  table: { width: '100%', borderCollapse: 'collapse', textAlign: 'left' },
  th: { padding: '18px 20px', color: '#475569', fontWeight: 'bold', fontSize: '14px', borderBottom: '2px solid #e2e8f0' },
  td: { padding: '15px 20px', fontSize: '14px' },
  deleteBtn: { padding: '6px 12px', backgroundColor: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }
};
